// Valida el contrato JSON v1 (docs/acuerdos/contrato-json.md).
// Salida 1: mensaje válido. Salida 2: mensaje rechazado.
const m = msg.payload;
const errores = [];

if (typeof m !== 'object' || m === null || Array.isArray(m)) {
    errores.push('el contenido no es un objeto JSON');
} else {
    if (m.schema !== 1) errores.push('schema debe ser 1');
    if (typeof m.node_id !== 'string' || m.node_id === '') errores.push('falta node_id');

    if (msg.topic === 'site/datos') {
        if (m.type !== 'rack' && m.type !== 'ambiente') errores.push('type debe ser rack o ambiente');
        if (!Number.isInteger(m.seq)) errores.push('falta seq entero');
        if (m.type === 'rack' && !Array.isArray(m.positions)) errores.push('rack sin positions');
    } else if (msg.topic.startsWith('site/estado/')) {
        if (m.status !== 'online' && m.status !== 'offline') errores.push('status debe ser online u offline');
        if (msg.topic !== 'site/estado/' + m.node_id) errores.push('el tema no coincide con node_id');
    }
}

if (errores.length) {
    msg.payload = { rechazado: errores, original: m };
    return [null, msg];
}
return [msg, null];
